"use client";
import Link from "next/link";
import { useCallback, useEffect, useState } from "react";
import { EmptyState, ErrorState, LoadingState } from "@/components/data-state";
import { StatusBadge } from "@/components/status-badge";
import { apiRequest } from "@/lib/api-client";
import { formatCurrency, formatDateTime } from "@/lib/format";
import type { OrderStatus, OrderSummary, PageResponse } from "@/types/api";

const openStatuses: OrderStatus[] = ["AWAITING_PAYMENT", "PAYMENT_SUBMITTED", "PAID", "PROCUREMENT_IN_PROGRESS", "OUT_FOR_DELIVERY", "DELIVERED"];
export function ClientDashboard() { const [open, setOpen] = useState<OrderSummary[] | null>(null); const [recent, setRecent] = useState<OrderSummary[] | null>(null); const [error, setError] = useState<string | null>(null);
  const load = useCallback(async () => { await Promise.resolve(); setError(null); try { const [openPages, completed] = await Promise.all([Promise.all(openStatuses.map((status) => apiRequest<PageResponse<OrderSummary>>(`orders?status=${status}&size=5`))), apiRequest<PageResponse<OrderSummary>>("orders?status=COMPLETED&size=5")]); setOpen(openPages.flatMap((page) => page.content).sort((a, b) => Date.parse(b.createdAt ?? "") - Date.parse(a.createdAt ?? "")).slice(0, 5)); setRecent(completed.content); } catch (caught) { setError(caught instanceof Error ? caught.message : "Your order overview could not be loaded."); } }, []);
  useEffect(() => { void Promise.resolve().then(load); }, [load]);
  if (error) return <ErrorState message={error} onRetry={() => void load()} />; if (!open || !recent) return <LoadingState label="Loading your order overview" />;
  return <div className="space-y-10"><section aria-labelledby="current-orders"><div className="mb-4 flex items-end justify-between gap-4"><div><p className="eyebrow">In progress</p><h2 id="current-orders" className="display-type mt-1 text-2xl">Current orders</h2></div><Link href="/orders" className="text-action">View all</Link></div>{open.length ? <OrderRows orders={open} current /> : <EmptyState title="No orders in progress" message="Build an order from the live catalogue when you are ready to procure." action={<Link className="button button-primary" href="/procure">Browse catalogue</Link>} />}</section><section aria-labelledby="recent-purchases"><div className="mb-4 flex items-end justify-between gap-4"><div><p className="eyebrow">Purchase record</p><h2 id="recent-purchases" className="display-type mt-1 text-2xl">Recently completed</h2></div><Link href="/history" className="text-action">Full history</Link></div>{recent.length ? <OrderRows orders={recent} /> : <EmptyState title="No completed purchases" message="Completed orders will form your purchase history here." />}</section></div>;
}
function OrderRows({ orders, current = false }: { orders: OrderSummary[]; current?: boolean }) { return <div className="border-y border-[var(--line-strong)]">{orders.map((order, index) => <Link key={order.reference} href={`/orders/${encodeURIComponent(order.reference)}`} className={`group grid gap-3 py-4 transition-colors hover:bg-[#f7f3eb] sm:grid-cols-[minmax(0,1fr)_11rem_9rem_auto] sm:items-center sm:px-3 ${index ? "border-t border-[var(--line)]" : ""}`}><div><div className="font-semibold text-[var(--forest-deep)]">{order.reference}</div><div className="mt-1 text-xs text-[var(--muted)]">{formatDateTime(order.createdAt)}</div></div><StatusBadge status={order.status} /><span className="font-semibold tabular-nums sm:text-right">{formatCurrency(order.totalAmount)}</span><span className="text-action sm:text-right">{current ? "Track order" : "View receipt"}</span></Link>)}</div>; }
